SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "辽史·卷四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38a4f1055550253802e2379fcd8a0add8913c3da/content/books/zizhi-tongjian/vol-286/year-0947/part-11/sources/library/liaoshi-004-march-deployment/source.txt", "note": "《辽史》卷四，段落 liaoshi-7cd182a20e67-p000581；EPUB电子本，纸本及异文待核", "id": "25110ae3-e00e-5835-a62d-4fe9a81b2257"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/tongjian-286-947-xuzhou-march/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003400；电子底本待考，分段待核", "id": "a967c8c3-a86b-5a6a-935c-f02f4127bba5"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/jiuwudaishi-099-march-rising/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002428；EPUB电子本，纸本及异文待核", "id": "1b396d07-3d8c-5388-8d7c-afd93f0c779b"}, {"title": "新五代史·卷十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/576d9a100a90791fb2103eff8dc0a2a9ed251986/content/books/zizhi-tongjian/vol-286/year-0947/part-07/sources/library/xinwudaishi-010-accession/source.txt", "note": "《新五代史》卷十，段落 xin-wudaishi-b08f244b9241-p000348；EPUB电子本，纸本及异文待核", "id": "f718016c-9527-5d8f-aa77-cf220d109f89"}, {"title": "新五代史·卷62·南唐世家·陈觉赴福州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/xinwudaishi-062-chen-jue-fuzhou/source.txt", "note": "《新五代史》卷62·南唐世家·陈觉赴福州，段落 xin-wudaishi-b08f244b9241-p003142；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "cef07fa0-ebe4-551b-8758-4a3b3e4794b6"}, {"title": "辽史·卷116·国语解·萧翰与后族姓名说法", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/11bd80a1278ae2081bb275997aefcffa5b947ddc/content/books/zizhi-tongjian/vol-285/year-0946/part-05/sources/library/liaoshi-116-xiao-kinship/source.txt", "note": "《辽史》卷116·国语解·萧翰与后族姓名说法，段落 liaoshi-7cd182a20e67-p005807；已回查正文卷题及上下文，纸本及异文待核。", "id": "df9ba9aa-ff1b-5b3e-b339-5387cd8fcc6e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "高允权", "aliases": ["高允權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高万金之子。947年延州军队攻周密，高允权获推为留后、据西城。《通鉴》称录事参军，《新五代史》追记开运时任肤施令、罢后居家，任职时点及写法分别保留。生卒年暂未录入。", "biography": null, "status": "draft", "id": "be6f380e-7cd3-5e5e-87d2-900104d55f65"}, {"name": "周密（后晋节度使）", "aliases": ["周密（後晉節度使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州人，后晋彰武节度使。947年延州将士攻他，战败后退保东城，与获推留后的高允权分据两城。与南宋同名作者区分，生卒年未载。", "biography": null, "status": "draft", "id": "798acc84-ada0-59ce-83be-19bc78b46946"}, {"name": "高彦珣", "aliases": ["高彥珣", "高彦询", "高彥詢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "丹州都指挥使。947年杀契丹委任的刺史，自管州务。当前《通鉴》此段写高彦珣，后段及《新五代史》写高彦询，《旧五代史》写高彥珣，依同一职务与事件识别为同人，引用保留各书字形。生卒年未载。", "biography": null, "status": "draft", "id": "f45f73c5-bcad-5722-933f-706d070dc315"}, {"name": "李昊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光三年条所见人物：李昊。", "biography": null, "status": "draft", "id": "ecf7855b-2568-576c-b0b9-58e6b1f120fa"}, {"name": "王处回", "aliases": ["王處回"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王处回，为税官请免的中门副使。", "biography": null, "status": "draft", "id": "159fd2b3-759b-522a-a971-11356c6fe970"}, {"name": "孙汉韶", "aliases": ["孫漢韶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：孙汉韶，武定节度使、合兵奏者。", "biography": null, "status": "draft", "id": "5e4dd4c6-73f4-51a3-a55b-930f6b95eac2"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "萧翰", "aliases": ["蕭翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。946年十一月条下记他与通事刘重进带兵绕到晋军后方，截断粮道及归路，进至栾城接受驻军投降。《资治通鉴》称他是契丹主耶律德光的舅舅，《辽史》保存了不同的亲属说法并质疑相关姓名起源说；具体亲属关系暂待核对。生卒年本批未核。", "biography": null, "status": "draft", "id": "defe15da-7bbc-56ed-9d88-0ec31a88fcaf"}, {"name": "余安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越将领。947年率水军从海道救援福州，三月己亥到白虾浦，与城内军队夹击南唐军，后领兵入福州，接管李仁达所部。生卒年未载。", "biography": null, "status": "draft", "id": "a2c3f143-466f-563b-a921-40cb3fdfd3a1"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "孟坚", "aliases": ["孟堅"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "南唐裨将。947年福州战事中，反对冯延鲁放吴越军登岸再围杀的计划，意见未被接受，随后战死。生年未载。", "biography": null, "status": "draft", "id": "4bdd4cf9-7c83-5621-865e-2dfe24d6b2dc"}, {"name": "王崇文", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐百胜军节度使。945年建州陷落后受任永安节度使，《资治通鉴》记他治理宽简，建州百姓渐安。生卒年本段未载。", "biography": null, "status": "draft", "id": "e00c8607-6426-5398-b911-e9eba22c7740"}, {"name": "刘洪进", "aliases": ["劉洪進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州战事中的南唐东南守将。947年听说吴越军可能撤离后，与其他将领建议王建封放其出城再取福州，未被采纳。生卒年未载。", "biography": null, "status": "draft", "id": "0cad1ad6-d61d-5ab1-b7a5-5499740ad0ab"}, {"name": "王建封", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上元人，南唐将领。945年《资治通鉴》记他以先锋桥道使身份率先登上建州城墙，南唐军随后攻破建州。生卒年本段未载。", "biography": null, "status": "draft", "id": "a7b5c6e1-9057-52ff-8317-f82698daacd6"}, {"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "李仁达", "aliases": ["李仁達", "李弘义", "李弘義", "李弘达", "李弘達", "李宏达", "李宏達", "李达", "李達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光州人，曾任闽元从指挥使，多次在建州、福州之间投奔不同执政者。945年与陈继珣、黄仁讽发动福州政变，杀王继昌和吴成义，拥立僧卓岩明。后来又杀黄仁讽、陈继珣，将福州兵权集中到自己手中。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "97ca7dea-54b1-5a38-a747-3dc803037d55"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "刘知远遣使持诏书，安抚聚居山谷躲避契丹的农民", "start_year": 947, "end_year": 947, "time_original": "947年三月戊子", "dynasty": "五代十国", "description": "刘知远遣使持诏书，安抚聚居山谷躲避契丹的农民。", "phases": [], "location_name": "农民避乱聚居的山谷，具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "039f1aad-ebc7-543a-aa88-4ec95dbb78a3"}, {"title": "高允权上表归附刘知远", "start_year": 947, "end_year": 947, "time_original": "947年三月辛卯", "dynasty": "五代十国", "description": "高允权上表归附刘知远。", "phases": [], "location_name": "延州至刘知远朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "83b62a2e-6d93-5a13-b418-4a542f4fe4e2"}, {"title": "刘知远命高允权允许周密到行在，周密放弃东城前来", "start_year": 947, "end_year": 947, "time_original": "947年三月辛卯条下，赴行在具体日未载", "dynasty": "五代十国", "description": "刘知远命高允权允许周密到行在，周密放弃东城前来。", "phases": [], "location_name": "延州东城至刘知远行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d0a6fdec-5504-5451-9297-decbb4f2c2e8"}, {"title": "高彦珣以丹州归附刘知远", "start_year": 947, "end_year": 947, "time_original": "947年三月壬辰", "dynasty": "五代十国", "description": "高彦珣以丹州归附刘知远。", "phases": [], "location_name": "丹州至刘知远朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fa469ae5-b51e-5bf8-b630-d32052dbf5bd"}, {"title": "李昊向王处回分析固镇、兴州援秦路线，建议孙汉韶急攻凤州", "start_year": 947, "end_year": 947, "time_original": "947年